-- Where the user is with the safety notice (FR-032): not acknowledged yet, so contacts are held back (SAFE-002);
-- acknowledged, so the app shows it once per match; or hidden after "don't show again". Replaces the acknowledgment
-- time, which nothing reads.
CREATE TYPE "safety_notice_state" AS ENUM ('not_acknowledged', 'acknowledged', 'hidden');

ALTER TABLE "profiles" ADD COLUMN "safety_notice" "safety_notice_state" NOT NULL DEFAULT 'not_acknowledged';

UPDATE "profiles" SET "safety_notice" = 'acknowledged' WHERE "safety_notice_ack_at" IS NOT NULL;

ALTER TABLE "profiles" DROP COLUMN "safety_notice_ack_at";
